import json, os, re, time

IN_PATH = 'storage/shared/meta/sas/beacons/logos_v.jsonl'
SUM_OUT = 'storage/shared/meta/sas/derived/hybrid_summary_logos_v.json'
PANEL_OUT = 'storage/shared/meta/sas/dashboard/hybrid_panel_logos_v.json'

def read_jsonl(path):
    rows = []
    try:
        with open(path, 'r', encoding='utf-8') as f:
            for line in f:
                line=line.strip()
                if not line: continue
                try: rows.append(json.loads(line))
                except Exception: pass
    except Exception:
        pass
    return rows

def num(x):
    try: return float(x)
    except Exception: return None

def ms_from(r):
    # accept op_cost_ms or op_cost
    v = r.get('op_cost_ms')
    if v is None: v = r.get('op_cost')
    return num(v)

rows = read_jsonl(IN_PATH)
deep = []
shallow = {}   # offset -> list of ms
r2 = {}        # offset -> list of deltas
baseline_shallow = []
baseline_sentinel = None

for r in rows:
    notes = (r.get('notes') or r.get('phase_label') or '').lower()
    m = ms_from(r)
    sd = num(r.get('sentinel_delta'))
    # baseline shallow (if labeled)
    if 'hybrid' in notes and 'baseline' in notes and 'shallow' in notes and m is not None:
        baseline_shallow.append(m)
        continue
    # baseline sentinel (if labeled)
    if 'baseline' in notes and sd is not None:
        baseline_sentinel = sd
    # deep triad
    if 'hybrid' in notes and 'deep' in notes and m is not None:
        deep.append(m)
        continue
    # shallow at offsets
    if 'hybrid' in notes and 'shallow' in notes and m is not None:
        mo = re.search(r'@\+(\d+)', notes)
        if mo:
            off = mo.group(1)
            shallow.setdefault(off, []).append(m)
        continue
    # recovery sentinel at offsets
    if 'r2' in notes and sd is not None:
        mo = re.search(r'@\+(\d+)', notes)
        if mo:
            off = mo.group(1)
            r2.setdefault(off, []).append(sd)

def mean(vs):
    return sum(vs)/len(vs) if vs else None

shallow_mean = {k: mean(v) for k, v in shallow.items()}
r2_mean = {k: mean(v) for k, v in r2.items()}
base_shallow_mean = mean(baseline_shallow)
deep_mean = mean(deep)

# ratios vs baseline shallow if available
shallow_ratio_vs_baseline = None
if base_shallow_mean and shallow_mean:
    shallow_ratio_vs_baseline = {
        k: (shallow_mean[k] / base_shallow_mean) for k in shallow_mean
    }

out = {
    "agent": "Logos V",
    "updated_ts": time.time(),
    "cpu_only": True,
    "baseline_sentinel_delta": baseline_sentinel,
    "baseline_shallow_ms": base_shallow_mean,
    "deep_ms": deep,
    "deep_mean_ms": deep_mean,
    "shallow_ms_mean": shallow_mean,
    "recovery_deltas": r2_mean,
    "shallow_ratio_vs_shallow_baseline": shallow_ratio_vs_baseline
}

os.makedirs(os.path.dirname(SUM_OUT), exist_ok=True)
with open(SUM_OUT, 'w', encoding='utf-8') as f:
    json.dump(out, f, indent=2)

panel = {
    "title": "HYBRID CES→XL Panel — Logos V",
    "agent": "Logos V",
    "experiment": "HYBRID_CES_XL",
    "updated_ts": out["updated_ts"],
    "deep_mean_ms": deep_mean,
    "shallow_ms_mean": shallow_mean,
    "recovery_deltas": r2_mean,
    "badges": {
        "trough_best": min(shallow_mean, key=lambda k: shallow_mean[k]) if shallow_mean else None
    },
    "notes": [
        "Provide baseline_shallow before deep triad to enable ratios.",
        "Prefer shallow at +2 (primary) and +6 (secondary); emit R2 at +2 and +4."
    ]
}
os.makedirs(os.path.dirname(PANEL_OUT), exist_ok=True)
with open(PANEL_OUT, 'w', encoding='utf-8') as f:
    json.dump(panel, f, indent=2)

print(json.dumps({
    "summary_path": SUM_OUT,
    "panel_path": PANEL_OUT,
    "counts": {
        "deep": len(deep),
        "shallow_offsets": {k: len(v) for k, v in shallow.items()},
        "r2_offsets": {k: len(v) for k, v in r2.items()}
    }
}, indent=2))

